import collections as C
def lines_rule(di,do):
    h=len(di); w=len(di[0])
    cnt=C.Counter(v for r in di for v in r).most_common(1)[0][0]
    mrows=[i for i in range(h) if any(di[i][j]!=cnt for j in range(w))]
    mcols=[j for j in range(w) if any(di[i][j]!=cnt for i in range(h))]
    out=[row[:] for row in di]
    colors={}
    for i in mrows: colors[i]=C.Counter(v for v in di[i] if v!=cnt).most_common(1)[0][0] if len(i)!=0 else None
    for j in mcols: colors[j]=C.Counter(v for v in [di[i][j] for i in range(h)] if v!=cnt).most_common(1)[0][0] if False else C.Counter(di[i][j] for i in range(h) if di[i][j]!=cnt).most_common(1)[0][0]
    for i in mrows:
        for j in range(w):
            out[i][j]=colors[i]
    for j in mcols:
        for i in range(h):
            out[i][j]=colors[j]
    return out==do
