G=load()
# For each demo, characterize bg->2 vs stay-bg vs marker-color regions by nearest-marker distance & same-row/col marker counts
def analyze(n):
    d=G[f'Demo pair {n} input']; o=G[f'Demo pair {n} output']
    h=len(d); w=len(d[0])
    bg=C.Counter(v for r in d for v in r).most_common(1)[0][0]
    marks=[(i,j,d[i][j]) for i in range(h) for j in range(w) if d[i][j]!=bg]
    # BFS distance per color
    def dists(sources):
        D=[[10**9]*w for _ in range(h)]; pq=[]
        for i,j,v in sources:
            D[i][j]=0; heapq.heappush(pq,(0,i,j))
        while pq:
            dd,a,b=heapq.heappop(pq)
            if dd>D[a][b]:continue
            for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                na,nb=a+dx,b+dy
                if 0<=na<h and 0<=nb<w and D[na][nb]>dd+1:
                    D[na][nb]=dd+1; heapq.heappush(pq,(dd+1,na,nb))
        return D
    Ds={c:dists([(i,j) for i,j,v in marks if v==c]) for c in {v for _,_,v in marks}}
    stats=collections.defaultdict(int)
    for i in range(h):
        for j in range(w):
            if d[i][j]==bg:
                do=o[i][j]
                f=(tuple(sorted(Ds[c][i][j] if c in Ds else None for c in sorted(Ds))), do)
                stats[f]+=1
    return stats
for n in range(1,8):
    s=analyze(n)
    print('pair',n,len(s),[(k,v) for k,v in s.items()][:6])

